"""Generate labeled, evergreen layout examples. Never run in publishing workflows."""
from common import ROOT, write
import html

STORIES = [
 ('Technology','A new way to look at the night sky starts with a little curiosity', 'Space exploration can feel distant. Public mission archives offer a closer look at the questions that keep us looking up.', 'NASA', 'https://science.nasa.gov/', ['Space','Discovery'], ['Space science begins with questions about the universe and our place in it. Public mission pages offer a starting point for exploring how researchers observe planets, stars and distant galaxies.', 'This demonstration article shows where an editor would explain a development, identify its source and describe what remains uncertain. It is an evergreen layout example, not a report about a new mission.', 'For real reporting, follow the source link and check the mission page directly. A published story should distinguish an observation from an interpretation and clearly identify the date of any announcement.']),
 ('Entertainment','Behind every great film is a world you rarely get to see','Look beyond the screen to explore the craft, collaboration and preservation of cinema.','Library of Congress','https://www.loc.gov/programs/national-film-preservation-board/', ['Film','Culture'], ['Film is both a creative work and a record of its time. Preservation helps audiences and researchers access that record beyond its original release.', 'This sample explainer demonstrates cultural coverage without inventing a premiere, a review or a quote. The linked National Film Preservation Board resource is a starting point for further reading.']),
 ('Sports','The stories that make sport bigger than the scoreboard','An introduction to the people, rules and shared experiences behind competition.','Olympics','https://olympics.com/ioc', ['Sport','Community'], ['A score records an outcome, but sports reporting can also examine preparation, rules and the organizations that shape a competition.', 'This is a demonstration of the sports section, not a live result or athlete profile. Check official event resources for dates, rules and confirmed results before publishing news.']),
 ('Business','Understanding the economy, one useful question at a time','A thoughtful starting point for reading economic headlines with more context.','World Bank','https://data.worldbank.org/', ['Economy','Data'], ['Economic indicators are measurements with definitions, collection periods and limitations. Reading those details is part of understanding what a headline actually means.', 'This example includes no current forecasts, investment recommendations or numerical claims. The World Bank data portal provides documentation for exploring indicators and their sources.']),
 ('Lifestyle','Make room for a slower, more curious kind of weekend','Small moments of discovery can start close to home, with a book, a walk or a new question.','UNESCO','https://www.unesco.org/en/culture', ['Culture','Everyday life'], ['Cultural experiences can take many forms, from reading and visiting local collections to learning about places and traditions.', 'This sample offers a general editorial theme rather than health advice or a recommendation about a specific destination. Use the source link to explore UNESCO’s cultural work.']),
 ('World News','A wider lens on the world starts with understanding the sources','Why original documents and clear attribution belong at the heart of global reporting.','United Nations','https://www.un.org/en/', ['World','Media literacy'], ['International reporting often draws on official statements, local reporting and documentary evidence. Each source has a perspective, and attribution helps readers evaluate a claim.', 'This is a sample media literacy explainer, not breaking news. For a real story, an editor should confirm the date and context of primary documents and seek additional reporting where claims are contested.'])
]

if __name__=='__main__':
    for i,(category,title,summary,source,url,tags,paragraphs) in enumerate(STORIES):
        slug='demo-'+category.lower().replace(' ','-')
        write(ROOT/'content/articles'/f'{slug}.json', dict(slug=slug,title=title,summary=summary,
            meta_description=summary[:160],category=category,author='The Current Editorial Desk',
            published_at=f'2026-10-{30-i:02d}T09:00:00Z',paragraphs=paragraphs,tags=tags,
            sources=[{'name':source,'url':url}],demo=True,status='published',featured=i==0))
    colors=[('#17332f','#b9d2b2','#e8874e'),('#4f2c38','#e0b6ac','#c5a268'),('#314c3b','#ced9b4','#ef9460'),('#263b48','#b8cbd0','#dc9964'),('#5b6645','#e1d7ac','#ba704b'),('#334649','#b1c6be','#d99e64')]
    for i,(category,*_) in enumerate(STORIES):
        bg,fg,accent=colors[i]
        # Locally authored vector artwork, with no third-party image license dependency.
        svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="640" viewBox="0 0 1000 640"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="{bg}"/><stop offset="1" stop-color="{fg}"/></linearGradient><pattern id="grain" width="8" height="8" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".6" fill="#ffffff" opacity=".13"/></pattern></defs><rect width="1000" height="640" fill="url(#sky)"/><circle cx="720" cy="210" r="112" fill="{accent}"/><circle cx="700" cy="185" r="111" fill="{bg}" opacity=".65"/><path d="M0 480 Q240 270 460 470 T1000 410 V640 H0Z" fill="{bg}"/><path d="M0 550 Q300 370 610 520 T1000 470 V640 H0Z" fill="{fg}" opacity=".4"/><path d="M0 600 Q240 490 480 590 T1000 540 V640 H0Z" fill="{bg}"/><path d="M430 640 L540 345 L650 640Z" fill="{accent}" opacity=".75"/><path d="M540 345 L650 640 H570Z" fill="{bg}" opacity=".7"/><path d="M150 170 H370 M260 60 V280" stroke="{fg}" stroke-width="1" opacity=".5"/><circle cx="260" cy="170" r="74" fill="none" stroke="{fg}" opacity=".5"/><g fill="{fg}"><circle cx="470" cy="120" r="3"/><circle cx="850" cy="90" r="2"/><circle cx="110" cy="310" r="2"/><circle cx="600" cy="75" r="2"/></g><rect width="1000" height="640" fill="url(#grain)"/></svg>'''
